function validate([slices]) {
  if (!Array.isArray(slices) || slices.length < 1 || slices.length > 500) return 'slices needs 1 to 500 values.';
  if (slices.length % 3 !== 0) return 'The number of slices must be a multiple of 3.';
  if (slices.some(v => !Number.isInteger(v) || v < 1 || v > 1000)) return 'Each slice size is a whole number from 1 to 1000.';
  return null;
}

