function maxSizeSlices(slices) {
  const picks = slices.length / 3;

  // Best total of up to `picks` slices from slices[from..to], no two side by side.
  function bestOnLine(from, to) {
    const length = to - from + 1;
    // dp[i][j]: best total using the first i slices of this line and taking at most j of them.
    const dp = Array.from({ length: length + 1 }, () => new Array(picks + 1).fill(0));
    for (let i = 1; i <= length; i++) {
      const size = slices[from + i - 1];
      for (let j = 1; j <= picks; j++) {
        const skip = dp[i - 1][j];
        const take = (i >= 2 ? dp[i - 2][j - 1] : 0) + size;
        dp[i][j] = Math.max(skip, take);
      }
    }
    return dp[length][picks];
  }

  // The first and last slices touch, so at least one of them is left out.
  const withoutLast = bestOnLine(0, slices.length - 2);
  const withoutFirst = bestOnLine(1, slices.length - 1);
  return Math.max(withoutLast, withoutFirst);
}

