function maxSizeSlices(slices) {
  // Play the game itself: try every slice you could take, remove it and both neighbours, recurse.
  const memo = new Map();
  function play(circle) {
    if (circle.length === 0) return 0;
    const key = circle.join(',');
    if (memo.has(key)) return memo.get(key);
    let best = 0;
    const k = circle.length;
    for (let i = 0; i < k; i++) {
      const gone = new Set([i, (i + 1) % k, (i - 1 + k) % k]);
      const rest = circle.filter((_, idx) => !gone.has(idx));
      best = Math.max(best, slices[circle[i]] + play(rest));
    }
    memo.set(key, best);
    return best;
  }
  return play(slices.map((_, i) => i));
}

