function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const n = size === 'large' ? 150 + pick(17) : 1 + pick(4);
  const top = size === 'large' || rand() < 0.4 ? 1000 : 1 + pick(9);
  const slices = Array.from({ length: 3 * n }, () => 1 + pick(top));
  if (size === 'small' && rand() < 0.25) {
    // Big values at both ends test the circular wrap-around.
    slices[0] = 1000;
    slices[slices.length - 1] = 1000;
  }
  return [slices];
}
